/* ---------- Motor de traducción ---------- */
window.VF = (function () {
  const SUPPORTED = ['es','en','fi','no'];
  const KEY = 'vf_lang';

  function detect() {
    const saved = localStorage.getItem(KEY);
    if (saved && SUPPORTED.includes(saved)) return saved;
    const nav = (navigator.languages || [navigator.language || 'es']).map(l => l.slice(0,2).toLowerCase());
    for (const l of nav) {
      if (l === 'nb' || l === 'nn') return 'no';
      if (SUPPORTED.includes(l)) return l;
    }
    return 'es';
  }

  let current = detect();

  function t(key) {
    const dict = window.VF_I18N[current] || window.VF_I18N.es;
    return dict[key] ?? window.VF_I18N.es[key] ?? key;
  }

  function apply(lang) {
    if (lang) current = SUPPORTED.includes(lang) ? lang : 'es';
    localStorage.setItem(KEY, current);
    document.documentElement.lang = current === 'no' ? 'nb' : current;

    document.querySelectorAll('[data-i18n]').forEach(el => {
      el.textContent = t(el.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      el.innerHTML = t(el.getAttribute('data-i18n-html'));
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
      el.placeholder = t(el.getAttribute('data-i18n-ph'));
    });

    const cur = document.getElementById('langCurrent');
    if (cur) cur.textContent = current.toUpperCase();
    document.querySelectorAll('.lang-menu [data-lang]').forEach(b => {
      b.setAttribute('aria-current', String(b.dataset.lang === current));
    });

    document.dispatchEvent(new CustomEvent('vf:lang', { detail: { lang: current } }));
  }

  return { t, apply, get lang() { return current; }, SUPPORTED };
})();
